import sys
from collections import Counter
def main():
    parts = sys.stdin.read().split()
    if not parts: return
    counts = Counter(parts)
    for k in sorted(counts.keys()):
        print(f"{k}: {counts[k]}")
if __name__ == '__main__': main()

